Node <https://w3id.org/nltl/benchmark/imo-batch-l/IMO-105-L-F03/ship> must conform to one or more shapes in [ sh:property [ sh:datatype xsd:boolean ; sh:hasValue Literal("false" = False, datatype=xsd:boolean) ; sh:message Literal("Discharge of oil or oily mixtures to sea must be recorded as false in Arctic_waters.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <https://w3id.org/nltl/vocab#oilOrOilyMixtureDischargeToSea> ], [ sh:datatype xsd:string ; sh:hasValue Literal("Arctic_waters") ; sh:message Literal("The operating area must be recorded as Arctic_waters when this branch applies.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <https://w3id.org/nltl/vocab#operatingArea> ] ; sh:sparql [ sh:message Literal("Oil or oily mixture discharge to sea must not have any value other than false in Arctic_waters.") ; sh:select Literal("
                    PREFIX nltl: <https://w3id.org/nltl/vocab#>
                    SELECT $this
                    WHERE {
                        $this nltl:operatingArea "Arctic_waters" .
                        FILTER NOT EXISTS {
                            $this nltl:oilOrOilyMixtureDischargeToSea ?discharge .
                            FILTER (?discharge != false)
                        }
                    }
                ") ] ] , [ sh:property [ sh:datatype xsd:string ; sh:message Literal("The operating area is required to determine whether the Arctic waters prohibition applies.") ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <https://w3id.org/nltl/vocab#operatingArea> ] ; sh:sparql [ sh:message Literal("This non-Arctic branch requires an operating area other than Arctic_waters.") ; sh:select Literal("
                    PREFIX nltl: <https://w3id.org/nltl/vocab#>
                    SELECT $this
                    WHERE {
                        FILTER NOT EXISTS {
                            $this nltl:operatingArea "Arctic_waters" .
                        }
                    }
                ") ] ]
